import encodings.idna as idna
import hashlib, json, pathlib, platform, random, sys, unicodedata

def fault(error):
    result = dict(name=type(error).__name__, message=str(error), suppressContext=error.__suppress_context__)
    if isinstance(error, (UnicodeEncodeError, UnicodeDecodeError)):
        result.update(encoding=error.encoding, object=list(map(ord,error.object)) if isinstance(error.object,str) else list(error.object), start=str(error.start), end=str(error.end), reason=error.reason)
    if error.__context__ is not None:
        result['context'] = fault(error.__context__)
    return result

rng = random.Random(0xED6E3147)
# Numeric construction prevents escaped text from replacing actual adversarial input.
points = [0, 0xad, 0x130, 0x378, 0x5d0, 0x627, 0x200d, 0x202e, 0x3002, 0xff0e, 0xff61, 0xff21, 0xd800, 0xdfff, 0x1f40d, 0x10ffff, 0xdf, 0x212b, 0x1e9e]
labels = ['', 'a', 'ABC', 'xn--', 'x'*63, 'x'*64] + [chr(point) for point in points]
text = []
for point in points:
    value = chr(point)
    text.extend([value, 'a.'+value, value+'.a', 'a.'+value+'.b', 'a..'+value, 'x'*64+'.'+value, value*64])
for _ in range(700):
    text.append(chr(rng.choice([46,0x3002,0xff0e,0xff61])).join(rng.choices(labels,k=rng.randrange(1,5))))
binary = []
for byte in range(128,256):
    for prefix in [b'', b'a.', b'xn--', b'a.xn--']:
        binary.append(prefix+bytes([byte])+b'.z')
for _ in range(700):
    binary.append(rng.choice([b'',b'a.',b'xn--',b'a.XN--'])+bytes(rng.choices(list(range(256)),k=rng.randrange(0,30))))
for size in [63,64,1024,1025]:
    for prefix in [b'',b'a.',b'xn--',b'a.xn--']:
        binary.append(prefix+b'x'*size)
cases=[]
for operation, inputs in [('encode',text),('decode',binary)]:
    for value in inputs:
        row=dict(operation=operation,input=list(map(ord,value)) if isinstance(value,str) else list(value),errors='strict')
        try:
            result,consumed=getattr(idna.Codec(),operation)(value)
            row.update(result=list(map(ord,result)) if isinstance(result,str) else list(result),consumed=consumed)
        except Exception as error:
            row['error']=fault(error)
        cases.append(row)
